import{WebSocketServer}from"ws";import{createJiti}from"jiti";import*as fs from"node:fs";import*as os from"node:os";import*as path from"node:path";import*as http from"node:http";import{fileURLToPath}from"node:url";const __dirname=path.dirname(fileURLToPath(import.meta.url));const jiti=createJiti(import.meta.url,{alias:{$core:path.join(__dirname,"../core")}});const{Truth}=await jiti.import("../core/truth.ts");const{serializeSnapshot,wireEventFromTruthEvent,hydrateSnapshot}=await jiti.import("../core/replica.ts");const{PROTOCOL_VERSION,DEFAULT_PORT}=await jiti.import("../core/protocol.ts");const{isDurableId}=await jiti.import("../core/wire.ts");const{applyGuardingHostOnly}=await jiti.import("../core/ops.ts");const{parse}=await jiti.import("../app/src/lib/engine/parse.ts");const{REGISTRY_PROTOCOL,REGISTRY_DIR,SESSIONS_SUBDIR,FOCUS_FILE,HEARTBEAT_INTERVAL_MS}=await jiti.import("../app/src/lib/live/registry.ts",);const PORT=Number(process.env.PORT||DEFAULT_PORT);const CONTROL_PORT=Number(process.env.CONTROL_PORT||PORT+1);const CW=Number(process.env.CW||60_000);const GROW=process.env.GROW!=="0";const SAMPLE=process.env.SAMPLE||path.join(__dirname,"../app/static/sample-session.jsonl");const sleep=(ms)=>new Promise((r)=>setTimeout(r,ms));const GENERATED=new Set(["thinking","text","tool_call"]);function kindPrefix(kind){if(kind==="user")return"u";if(kind==="tool_result")return"r";return"a";}function loadBaseBlocks(){const raw=fs.readFileSync(SAMPLE,"utf8");const{meta,blocks}=parse(raw);const turnSpan=blocks.reduce((m,b)=>Math.max(m,b.turn),0)+1;return{meta,blocks,turnSpan,orderSpan:blocks.length};}function toBlock(b,loop,turnSpan,orderSpan){return{id:`${kindPrefix(b.kind)}:L${loop}:${b.id}`,kind:b.kind,turn:b.turn+loop*turnSpan,order:b.order+loop*orderSpan,text:b.text,tokens:b.tokens,toolName:b.toolName,callId:b.callId!=null?`${b.callId}#L${loop}`:undefined,model:b.model,isError:b.isError,override:null,autoFolded:false,by:null,subst:undefined,};}const{meta,blocks,turnSpan,orderSpan}=loadBaseBlocks();if(process.argv.includes("--selftest")){const hist={};for(const b of blocks)hist[b.kind]=(hist[b.kind]||0)+1;const loopBlocks=blocks.map((b)=>toBlock(b,0,turnSpan,orderSpan));const foldable=loopBlocks.filter((b)=>b.kind==="thinking"||b.kind==="text"||b.kind==="tool_result");const allFoldableDurable=foldable.every((b)=>isDurableId(b.id));const totalTokens=loopBlocks.reduce((s,b)=>s+b.tokens,0);const callIds=new Set(loopBlocks.filter((b)=>b.kind==="tool_call").map((b)=>b.callId));const orphanResults=loopBlocks.filter((b)=>b.kind==="tool_result"&&b.callId&&!callIds.has(b.callId)).length;const t=new Truth({meta:{format:"pi",title:meta.title||"",cwd:meta.cwd||"",model:meta.model||""},blocks:[],lineCount:0,skipped:0});t.wireAttached=true;t.setContextWindow(CW);t.setBudget(CW);const revBefore=t.rev;t.append(loopBlocks);const revAfterAppend=t.rev;const snap=serializeSnapshot(t,false);const rebuilt=hydrateSnapshot(t.meta,snap);const roundTrips=rebuilt.rev===t.rev&&rebuilt.blocks.length===t.blocks.length;console.log("title:",meta.title,"| model:",meta.model);console.log("blocks:",blocks.length,"| kinds:",JSON.stringify(hist));console.log("turnSpan:",turnSpan,"| total tokens:",totalTokens);console.log("protocol version:",PROTOCOL_VERSION);console.log("first ids:",loopBlocks.slice(0,5).map((b)=>b.id));console.log("all foldable ids durable:",allFoldableDurable);console.log("orphan tool_results (want 0):",orphanResults);console.log("truth rev progressed on append:",revBefore,"->",revAfterAppend);console.log("snapshot/hydrate round-trips:",roundTrips);if(!allFoldableDurable||orphanResults>0||revAfterAppend<=revBefore||!roundTrips){console.error("SELFTEST FAILED");process.exit(1);}console.log("SELFTEST OK");process.exit(0);}let playing=false;let tps=Math.max(1,Number(process.env.TPS||60));let epoch=0;let loop=0;let idx=0;const startedAt=Date.now();const apps=new Set();const controls=new Set();const sessionId="fake-"+process.pid;const send=(ws,obj)=>{try{ws.send(JSON.stringify(obj));}catch{}};function broadcastApps(obj){const s=JSON.stringify(obj);for(const ws of apps){if(ws.readyState!==1)continue;try{ws.send(s);}catch{}}}let truth=null;let unsubTruth=null;let foldingEnabled=false;function metaForTruth(){return{format:"pi",title:meta.title||"FAKE pi session",cwd:meta.cwd||"fake://sample",model:meta.model||"fake-model"};}function metaWire(){return{...metaForTruth(),contextWindow:CW};}function setFolding(on){if(foldingEnabled===on)return;foldingEnabled=on;broadcastApps({type:"folding",enabled:foldingEnabled});}function buildTruth(){if(unsubTruth){unsubTruth();unsubTruth=null;}const t=new Truth({meta:metaForTruth(),blocks:[],lineCount:0,skipped:0});t.wireAttached=true;t.setContextWindow(CW);t.setBudget(CW);unsubTruth=t.onEvent((e)=>{const ev=wireEventFromTruthEvent(e);if(ev)broadcastApps({type:"event",event:ev});});truth=t;}buildTruth();function applyCommand(cmd){if(!truth)return{results:[],rev:0};switch(cmd.kind){case"ops":{const r=applyGuardingHostOnly(Array.isArray(cmd.ops)?cmd.ops:[],(allowed)=>truth.apply(allowed,"you"));return{results:r.results,rev:r.rev};}case"setBudget":truth.setBudget(cmd.value);return{results:[],rev:truth.rev};case"setProtect":truth.setProtect(cmd.value);return{results:[],rev:truth.rev};case"setFolding":setFolding(!!cmd.value);return{results:[],rev:truth.rev};case"selectConductor":return{results:[],rev:truth.rev};default:return{results:[],rev:truth.rev};}}function statusObj(){const cur=blocks[idx];return{type:"status",playing,tps,loop,grow:GROW,turn:cur?cur.turn+loop*turnSpan:0,blocksStreamed:truth.blocks.length,totalTokens:truth.fullTokens(),budget:CW,appsConnected:apps.size,sessionTitle:meta.title,sessionBlocks:blocks.length,};}function pushStatus(){const s=JSON.stringify(statusObj());for(const ws of controls)try{ws.send(s);}catch{}}function emitBlock(block){truth.append([block]);}function doRestart(){epoch++;loop=0;idx=0;buildTruth();broadcastApps({type:"snapshot",state:serializeSnapshot(truth,foldingEnabled)});pushStatus();}async function pacedWait(tokens,myEpoch){let progress=0;const slice=50;while(progress<tokens){if(!playing||epoch!==myEpoch)return false;await sleep(slice);progress+=tps*(slice/1000);}return playing&&epoch===myEpoch;}async function genLoop(){for(;;){if(!playing){await sleep(80);continue;}const myEpoch=epoch;const block=toBlock(blocks[idx],loop,turnSpan,orderSpan);if(GENERATED.has(block.kind)){broadcastApps({type:"stream",phase:"start",kind:block.kind,contentIndex:idx});const ok=await pacedWait(block.tokens,myEpoch);broadcastApps({type:"stream",phase:"abort",kind:block.kind,contentIndex:-1});if(!ok)continue;emitBlock(block);}else{if(epoch!==myEpoch)continue;emitBlock(block);await sleep(10);}idx++;if(idx>=blocks.length){idx=0;loop++;if(!GROW){epoch++;buildTruth();broadcastApps({type:"snapshot",state:serializeSnapshot(truth,foldingEnabled)});}}pushStatus();}}const accordionHome=process.env.ACCORDION_HOME||os.homedir();const sessionsDir=path.join(accordionHome,REGISTRY_DIR,SESSIONS_SUBDIR);const entryPath=path.join(sessionsDir,sessionId+".json");function writeEntry(){const entry={registryProtocol:REGISTRY_PROTOCOL,protocolVersion:PROTOCOL_VERSION,sessionId,port:PORT,pid:process.pid,cwd:meta.cwd||"fake://sample",title:meta.title||"FAKE pi session",model:meta.model||"fake-model",tokens:truth?truth.fullTokens():null,contextWindow:CW,startedAt,heartbeatAt:Date.now(),};try{fs.writeFileSync(entryPath,JSON.stringify(entry));}catch{}}function removeEntry(){try{fs.unlinkSync(entryPath);}catch{}}const focusPath=path.join(accordionHome,REGISTRY_DIR,FOCUS_FILE);function writeFocus(){try{fs.writeFileSync(focusPath,JSON.stringify({sessionId,ts:Date.now()}));console.log("focus request written (simulated /accordion)");}catch{}}fs.mkdirSync(sessionsDir,{recursive:true});writeEntry();const heartbeat=setInterval(writeEntry,HEARTBEAT_INTERVAL_MS);let shuttingDown=false;function shutdown(){if(shuttingDown)return;shuttingDown=true;clearInterval(heartbeat);removeEntry();process.exit(0);}process.on("SIGINT",shutdown);process.on("SIGTERM",shutdown);process.on("exit",removeEntry);const piWss=new WebSocketServer({host:"127.0.0.1",port:PORT});piWss.on("connection",(ws)=>{apps.add(ws);console.log(`Accordion connected (${apps.size} attached)`);send(ws,{type:"hello",protocolVersion:PROTOCOL_VERSION,sessionId,role:"gui",meta:metaWire()});send(ws,{type:"snapshot",state:serializeSnapshot(truth,foldingEnabled)});send(ws,{type:"telemetry",lastHookMs:0,maxHookMs:0,p95HookMs:0,rebuilds:0,hookCount:0,lastHoldMs:0,holdTimeouts:0});pushStatus();ws.on("message",(d)=>{let m;try{m=JSON.parse(d.toString());}catch{return;}if(m?.type==="command"&&typeof m.seq==="number"&&m.cmd&&typeof m.cmd==="object"){const{results,rev}=applyCommand(m.cmd);send(ws,{type:"commandResult",seq:m.seq,results,rev});}else if(m?.type==="resnapshot"){send(ws,{type:"snapshot",state:serializeSnapshot(truth,foldingEnabled)});}});ws.on("close",()=>{apps.delete(ws);console.log(`Accordion disconnected (${apps.size} attached)`);pushStatus();});});const controlHtmlPath=path.join(__dirname,"control.html");const httpServer=http.createServer((req,res)=>{if(req.url==="/"||req.url==="/index.html"){fs.readFile(controlHtmlPath,(err,buf)=>{if(err){res.writeHead(500);res.end("control.html missing");return;}res.writeHead(200,{"content-type":"text/html; charset=utf-8"});res.end(buf);});}else{res.writeHead(404);res.end("not found");}});const controlWss=new WebSocketServer({server:httpServer,path:"/ws"});controlWss.on("connection",(ws)=>{controls.add(ws);send(ws,statusObj());ws.on("message",(d)=>{let m;try{m=JSON.parse(d.toString());}catch{return;}switch(m.cmd){case"play":playing=true;break;case"pause":playing=false;break;case"restart":doRestart();break;case"focus":writeFocus();break;case"tps":if(Number.isFinite(m.value))tps=Math.max(1,Math.min(100_000,m.value));break;}pushStatus();});ws.on("close",()=>controls.delete(ws));});httpServer.listen(CONTROL_PORT,"127.0.0.1");setInterval(()=>{if(controls.size)pushStatus();},1000);setInterval(()=>{if(apps.size)broadcastApps({type:"telemetry",lastHookMs:0,maxHookMs:0,p95HookMs:0,rebuilds:0,hookCount:0,lastHoldMs:0,holdTimeouts:0});},2000);void genLoop();console.log(`fake pi ready (paused)\n`+`  session : "${meta.title}" — ${blocks.length} blocks, advertised as ${sessionId}\n`+`  protocol: v${PROTOCOL_VERSION} (core/protocol.ts, loaded live via jiti)\n`+`  pi-wire : ws://127.0.0.1:${PORT}   (desktop app discovers it via ~/.accordion)\n`+`  control : http://localhost:${CONTROL_PORT}   ← open this in a browser\n`+`  TPS=${tps}  CW=${CW}  GROW=${GROW ? 1 : 0}`,);